import re
from typing import Dict, List, Tuple

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    def interpolate(value: str, section: str, seen: set) -> str:
        while True:
            match = re.search(r'\$\{([^}]+)\}', value)
            if not match:
                break
            ref = match.group(1)
            if ':' in ref:
                ref_section, ref_key = ref.split(':', 1)
            else:
                ref_section = section
                ref_key = ref.lower()

            if (ref_section, ref_key) in seen:
                raise ValueError(f"Reference cycle detected: {ref}")
            seen.add((ref_section, ref_key))

            if ref_section == 'DEFAULT':
                if ref_key not in default_section:
                    raise KeyError(f"Missing key in DEFAULT: {ref_key}")
                ref_value = default_section[ref_key]
            elif ref_section in sections:
                if ref_key not in sections[ref_section]:
                    if ref_key in default_section:
                        ref_value = default_section[ref_key]
                    else:
                        raise KeyError(f"Missing key in section {ref_section}: {ref_key}")
                else:
                    ref_value = sections[ref_section][ref_key]
            else:
                raise KeyError(f"Missing section: {ref_section}")

            value = value.replace(match.group(0), ref_value)
            seen.discard((ref_section, ref_key))
        return value

    sections: Dict[str, Dict[str, str]] = {}
    default_section: Dict[str, str] = {}
    current_section: str = 'DEFAULT'

    lines = text.splitlines()
    buffer: List[str] = []

    for line in lines:
        line = line.strip()
        if not line or line.startswith((';', '#')):
            continue

        if line.startswith(('[', ']')):
            match = re.match(r'\[(\w+)\]', line)
            if match:
                if buffer:
                    sections[current_section][buffer[0].strip().lower()] = '\n'.join(buffer[1:])
                    buffer.clear()
                current_section = match.group(1)
                if current_section not in sections:
                    sections[current_section] = {}
            else:
                raise ValueError(f"Malformed section header: {line}")
        elif '=' in line or ':' in line:
            if buffer:
                sections[current_section][buffer[0].strip().lower()] = '\n'.join(buffer[1:])
                buffer.clear()
            key, value = re.split(r'[=:]', line, maxsplit=1)
            key = key.strip().lower()
            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]
            else:
                value = value.strip()
                comment_start = value.find(' ;')
                if comment_start == -1:
                    comment_start = value.find(' #')
                if comment_start != -1:
                    value = value[:comment_start]
            buffer.append(key)
            buffer.append(value)
        elif line.startswith((' ', '\t')):
            if buffer:
                buffer.append(line.strip())
            else:
                raise ValueError(f"Continuation line without preceding key: {line}")
        else:
            raise ValueError(f"Malformed key-value pair: {line}")

    if buffer:
        sections[current_section][buffer[0].strip().lower()] = '\n'.join(buffer[1:])

    if current_section != 'DEFAULT':
        default_section = sections.pop('DEFAULT', {})

    for section in sections.values():
        for key in section.keys():
            section[key] = interpolate(section[key], current_section, set())

    return sections
