def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Empty or blank string")

    total_seconds = 0
    used_units = set()
    current_number = ""
    last_unit = ""
    s = s.strip() + " "  # Add a space to process the last unit

    for i, char in enumerate(s):
        if char.isdigit():
            current_number += char
        elif char.isspace():
            if current_number:
                if last_unit:
                    raise ValueError("Numbers must be followed by a unit")
                continue
        elif char.lower() in {'h', 'm', 's'}:
            if not current_number:
                raise ValueError("Unit must be preceded by a number")
            value = int(current_number)
            unit = char.lower()
            if unit in used_units:
                raise ValueError(f"Unit '{char}' appears more than once")
            if (last_unit and (last_unit == 'h' and unit != 'm') or
                last_unit == 'm' and unit == 'h'):
                raise ValueError("Units must appear in the order h, m, s")
            if unit == 'h':
                total_seconds += value * 3600
            elif unit == 'm':
                total_seconds += value * 60
            else:  # unit == 's'
                total_seconds += value
            used_units.add(unit)
            last_unit = unit
            current_number = ""
        else:
            raise ValueError(f"Unknown unit '{char}'")

    return total_seconds
