from decimal import Decimal
from typing import List, Dict, Tuple

def parse_amount(amount: str) -> Decimal:
    amount = amount.replace('$', '').replace(',', '')
    return Decimal(amount)

def top_customers(rows: List[Dict[str, str]], n: int) -> List[Tuple[str, float]]:
    customer_sums = {}

    for row in rows:
        customer = row['customer'].strip()
        if not customer:
            continue

        try:
            amount = parse_amount(row['amount'])
        except (ValueError, Decimal):
            continue

        if customer.lower() not in customer_sums:
            customer_sums[customer.lower()] = {'name': customer, 'total': Decimal(0)}

        customer_sums[customer.lower()]['total'] += amount

    sorted_customers = sorted(customer_sums.values(), key=lambda x: (-x['total'], x['name']))

    result = [(customer['name'], round(float(customer['total']), 2)) for customer in sorted_customers[:n]]

    return result
